=WITH output_insert AS (
  INSERT INTO content_outputs (job_id, output_type, title, structured_data, body_markdown, qa_status)
  VALUES (NULLIF('{{$json.job_id}}','')::uuid, 'content_plan', 'Content Plan', '{{$json.output_sql}}'::jsonb, NULLIF('{{$json.body_markdown_sql}}',''), 'pending')
  RETURNING id
), task_update AS (
  UPDATE content_tasks SET status='completed', output_payload='{{$json.output_sql}}'::jsonb, updated_at=now()
  WHERE job_id=NULLIF('{{$json.job_id}}','')::uuid AND task_key='generate_content_plan'
  RETURNING id
), job_update AS (UPDATE content_jobs SET status='waiting_for_plan_approval'::job_status, updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid RETURNING id), event_insert AS (
  INSERT INTO content_events (job_id,event_type,message,metadata)
  SELECT NULLIF('{{$json.job_id}}','')::uuid,'output_stored','Output stored: content_plan',jsonb_build_object('output_id',(SELECT id FROM output_insert),'source','{{$json.source}}')
)
SELECT (SELECT id::text FROM output_insert) AS output_id;

=WITH err AS (
  INSERT INTO content_errors (job_id,severity,error_code,error_message,recoverable,context)
  VALUES (NULLIF('{{$json.job_id}}','')::uuid,'high','LLM_HTTP_ERROR',COALESCE(NULLIF('{{$json.error_message || ""}}',''),'LLM HTTP request failed'),true,jsonb_build_object('workflow','generate_content_plan'))
  RETURNING id
), event_insert AS (
  INSERT INTO content_events (job_id,event_type,message,metadata)
  SELECT NULLIF('{{$json.job_id}}','')::uuid,'llm_error_logged','LLM error logged',jsonb_build_object('error_id',(SELECT id FROM err))
)
SELECT id::text AS error_id FROM err;
